        double XSUBB = sqrt(V(0)*V(0) + V(1)*V(1));
        if (XSUBB < 1e-12) continue;
        double U1 = V(0) / XSUBB;
        double U2 = V(1) / XSUBB;

        MatrixXd T(3, 3);
        T << 1.0, 0.0, 0.0,
             0.0, U1, U2,
             0.0, -U2, U1;

        // Assemble contributions from all 9 submatrices in K_super_U
        // Indexing: K_super_U[i] corresponds to a 3x3 block
        // We'll map each K_super_U[k] to appropriate global DOF pair
        for (int k = 0; k < 9; ++k) {
            if (k >= K_super_U.size()) continue;
            const MatrixXd& K_block = K_super_U[k];
            if (K_block.rows() != 3 || K_block.cols() != 3) continue;

            // Transform
            MatrixXd transformed = T * K_block * T.transpose();

            // Determine node indices for this block
            // Mapping per Fortran logic (simplified):
            // For triangle (a,b,c), blocks correspond to (a,a), (a,b), (a,c), (b,a), (b,b), (b,c), (c,a), (c,b), (c,c)
            int tri_a = triangles[j][0];
            int tri_b = triangles[j][1];
            int tri_c = triangles[j][2];
            int node_i, node_k;

            if (k < 3) {
                node_i = tri_a;
                node_k = (k == 0) ? tri_a : (k == 1) ? tri_b : tri_c;
            } else if (k < 6) {
                node_i = tri_b;
                node_k = (k == 3) ? tri_a : (k == 4) ? tri_b : tri_c;
            } else {
                node_i = tri_c;
                node_k = (k == 6) ? tri_a : (k == 7) ? tri_b : tri_c;
            }

            int row_start = node_i * 3;
            int col_start = node_k * 3;

            if (row_start < 12 && col_start < 12) {
                K_full.block(row_start, col_start, 3, 3) += transformed;
            }
        }
    }

    // Enforce symmetry
    K_full = (K_full + K_full.transpose()) / 2.0;

    return K_full;
}

